// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        c.OpenToThePublic();
        vm.deal(address(this), amount);
        bool ok;
        try c.donate{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint256 amount) public {
        c.AdjustBetAmounts(amount);
        assert(c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(uint256 a, uint256 b) public {
        c.AdjustBetAmounts(a);
        c.AdjustBetAmounts(b);
        assert(c.currentBetLimit() == b);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 newLimit) public {
        c.AdjustBetAmounts(newLimit);
        assert(c.currentBetLimit() == newLimit);
    }
    receive() external payable {}
    fallback() external payable {}
}

