    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        c.AdjustDifficulty(amount);
        assert(c.currentDifficulty() == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(uint256 amount) public {
        require(amount > 0);
        c.AdjustDifficulty(amount);
        assert(c.currentDifficulty() == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        require(amount != c.currentBetLimit());
        c.AdjustDifficulty(amount);
        assert(c.currentDifficulty() == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNonOwnerCannotAdjustDifficulty(uint256 amount) public {
        require(amount > 0);
        // This contract is not the owner of c (c was deployed by someone else),
        // so AdjustDifficulty must revert on P and succeed on M.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustDifficulty.selector, amount));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test() public {
        require(c.currentBetLimit() == 0);
        // owner (this contract deployed C? owner is msg.sender of deployment) — instead drive from parameter
        (bool okOwner, ) = address(c).call(abi.encodeWithSelector(c.OpenToThePublic.selector));
        (bool okAdjust, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, uint256(5)));
        assert(okOwner && okAdjust);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address ownerAddr, uint256 amount) public {
        require(address(this) != ownerAddr);
        bool reverted; try c.AdjustDifficulty(amount) { reverted = false; } catch { reverted = true; }   // boundary
        assert(reverted);
    }
    receive() external payable {}
}
